securityRules.rules:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /sessions/{sessionId} {
      allow read: if true;
      allow write: if request.resource.data.id is string && request.resource.data.id.size() > 0 && request.resource.data.id.size() <= 64;
    }
    match /users/{userId} {
      allow read: if true;
      allow write: if request.auth != null && request.auth.uid == userId;
    }
    match /playerProfiles/{profileId} {
      allow read: if true;
      allow write: if request.resource.data.name is string && request.resource.data.name.size() > 0;
    }
  }
}
